 out.push(...l.words.map(w=>({type:'listen',prompt:'اسمع واختار المعنى',source:w.es,answer:w.ar,options:shuffled(l.words.map(x=>x.ar)),word:w})));
 out.push(...l.words.map(w=>bankQ(w,'es')));out.push({type:'match',prompt:'ثبّت الكلمات: وصّل تاني',words:l.words});
 out.push({type:'dialoggap',prompt:'كمّل الكلمة الناقصة في الحوار',source:d[0],answer:d[1].split(' ').at(-1),response:d[1],prefix:d[1].split(' ').slice(0,-1).join(' '),options:shuffled([...new Set([d[1].split(' ').at(-1),...l.words.map(w=>w.es.split(' ').at(-1)).filter(x=>x!==d[1].split(' ').at(-1)).slice(0,2)])]),meaning:d[2],responseMeaning:d[3]});
 out.push(...l.words.map(w=>({type:'speak',prompt:'اسمع وكرّر بصوتك',source:w.es,answer:w.es,meaning:w.ar,word:w})));
 const a=l.words[l.index%l.words.length],parts=a.es.split(' '),last=parts.pop();
 out.push({type:'gap',prompt:'كمّل الكلمة الناقصة',source:(parts.join(' ')+' ____').trim(),answer:last,options:shuffled([...new Set([last,...l.words.filter(w=>w.id!==a.id).map(w=>w.es.split(' ').at(-1))])]),meaning:a.ar,word:a});
 out.push({type:'dialogreply',prompt:'اختار الرد اللي معناه المطلوب',source:d[0],answer:d[1],options:shuffled([d[1],d[1]==='No sé'?'Un momento':'No sé']),meaning:d[2],responseMeaning:d[3]});
 out.push({type:'dialog',prompt:'اختار الرد اللي معناه المطلوب',source:d[0],answer:d[1],options:shuffled([...new Set([d[1],'No sé','Un momento'])]),meaning:d[2],responseMeaning:d[3]});
